# New JavaScript basics: one question per commonly asked method that had no question.
# Each item: title, note (first-person answer), topic placement (after which title),
# and steps: ('stmt', code) runs a line; ('expr', code, comment) shows a value.
ITEMS = [
 dict(title="What is the difference between indexOf() and lastIndexOf()?", after="What does indexOf do?",
  note="indexOf searches from the start and returns the first position of a value, while lastIndexOf searches from the end and returns the last position. Both return -1 when the value isn't there, and both work on strings too. I combine them to check if a value appears only once: indexOf(x) === lastIndexOf(x).",
  steps=[('stmt',"const nums = [1, 2, 3, 2, 1]"),('expr',"nums.indexOf(2)","first 2 is at index 1"),('expr',"nums.lastIndexOf(2)","last 2 is at index 3"),('expr',"nums.indexOf(9)","not found"),('expr',"'banana'.lastIndexOf('a')","works on strings too")]),
 dict(title="What do push(), pop(), shift() and unshift() return?", after="How do you add, update and remove items in an array?",
  note="push and unshift add items to the end or the start and return the new length. pop and shift remove one item from the end or the start and return that removed item. All four change the original array, so in React state I use spread or slice instead.",
  steps=[('stmt',"const arr = ['b', 'c']"),('expr',"arr.push('d')","new length"),('expr',"arr.unshift('a')","new length"),('expr',"arr.pop()","removed item"),('expr',"arr.shift()","removed item"),('expr',"arr","back to the start")]),
 dict(title="What does reverse() do?", after="What are toSorted, toReversed and with?",
  note="reverse() reverses the array in place, so it changes the original and also returns it. If I need to keep the original, I use toReversed() or [...arr].reverse(). Strings don't have reverse(), so I split, reverse and join.",
  steps=[('stmt',"const arr = [1, 2, 3]"),('expr',"[...arr].reverse()","copy reversed, original kept"),('expr',"arr","unchanged"),('expr',"arr.reverse()","reverses the original"),('expr',"'hello'.split('').reverse().join('')","reverse a string")]),
 dict(title="What does reduceRight() do?", after="What does reduce do?",
  note="reduceRight works like reduce, but it goes through the array from the last item to the first. I rarely need it, but it's handy when order matters, like composing functions right to left.",
  steps=[('expr',"['a', 'b', 'c'].reduce((acc, x) => acc + x, '')","left to right"),('expr',"['a', 'b', 'c'].reduceRight((acc, x) => acc + x, '')","right to left")]),
 dict(title="How do you check if a value is an array?", after="How do you create arrays and objects and read values from them?",
  note="I use Array.isArray(value), which returns true only for real arrays. typeof doesn't help, because it returns 'object' for arrays, objects and null.",
  steps=[('expr',"Array.isArray([1, 2])","true"),('expr',"Array.isArray('abc')","false"),('expr',"Array.isArray({ length: 2 })","false: array-like, not an array"),('expr',"typeof [1, 2]","'object', so typeof can't tell")]),
 dict(title="How does the length property of an array work?", after="How do you check if a value is an array?",
  note="length is always one more than the highest index, so arr[arr.length - 1] is the last item. It's also writable: setting a smaller length cuts the array, and arr.length = 0 empties it in place.",
  steps=[('stmt',"const arr = [10, 20, 30, 40]"),('expr',"arr.length",""),('expr',"arr[arr.length - 1]","last item"),('stmt',"arr.length = 2   // cut the array"),('expr',"arr",""),('stmt',"arr.length = 0   // empty it"),('expr',"arr","")]),
 dict(title="What are Array.of(), toSpliced() and copyWithin()?", after="What does Array.from do?",
  note="Array.of builds an array from its arguments, which avoids the Array(7) trap where one number means a length. toSpliced is the non-mutating version of splice and returns a new array. copyWithin copies part of an array over another part of the same array; I almost never use it, but it's good to recognise.",
  steps=[('expr',"Array(3)","3 empty slots, not [3]"),('expr',"Array.of(3)",""),('expr',"[1, 2, 3, 4].toSpliced(1, 2)","original unchanged"),('expr',"[1, 2, 3, 4, 5].copyWithin(0, 3)","copy index 3.. to index 0")]),

 dict(title="How do you get a character from a string (charAt, [], at, charCodeAt)?", after="What are the common string methods?",
  note="I read a character with str[i] or charAt(i), and use at(-1) for the last character. charCodeAt gives the character's number code, and String.fromCharCode turns codes back into text. Strings are immutable, so these only read characters, they never change them.",
  steps=[('stmt',"const s = 'hello'"),('expr',"s[0]",""),('expr',"s.charAt(1)",""),('expr',"s.at(-1)","last character"),('expr',"s.charCodeAt(0)","code of 'h'"),('expr',"String.fromCharCode(72, 105)","")]),
 dict(title="How do you change case and trim spaces in a string?", after="How do you get a character from a string (charAt, [], at, charCodeAt)?",
  note="toUpperCase and toLowerCase change the case, and trim removes spaces from both ends, with trimStart and trimEnd for one side. They all return a new string. I trim and lowercase user input before comparing, like emails.",
  steps=[('stmt',"const s = '  Hello World  '"),('expr',"s.trim()",""),('expr',"s.trimStart()",""),('expr',"s.trimEnd()",""),('expr',"s.trim().toUpperCase()",""),('expr',"s.trim().toLowerCase()","")]),
 dict(title="What do padStart(), padEnd() and repeat() do?", after="How do you change case and trim spaces in a string?",
  note="padStart and padEnd add characters to the start or end until the string reaches a length, which I use for things like zero-padded numbers or aligned text. repeat returns the string repeated a number of times.",
  steps=[('expr',"'5'.padStart(3, '0')","zero-pad"),('expr',"'7'.padStart(2, '0') + ':' + '5'.padStart(2, '0')","time format"),('expr',"'abc'.padEnd(6, '.')",""),('expr',"'ab'.repeat(3)","")]),
 dict(title="What is the difference between replace() and replaceAll()?", after="What do padStart(), padEnd() and repeat() do?",
  note="replace with a string changes only the first match, while replaceAll changes every match. Before replaceAll existed I used a regex with the g flag. Both return a new string and leave the original as it is.",
  steps=[('stmt',"const s = 'a-b-c'"),('expr',"s.replace('-', '+')","first match only"),('expr',"s.replaceAll('-', '+')","every match"),('expr',"s.replace(/-/g, '+')","regex with g flag"),('expr',"s","original unchanged")]),
 dict(title="What is the difference between slice(), substring() and substr() for strings?", after="What is the difference between replace() and replaceAll()?",
  note="slice(start, end) and substring(start, end) both cut out part of a string, but slice accepts negative indexes that count from the end, while substring treats negatives as 0. substr(start, length) uses a length instead of an end and is deprecated, so I use slice in new code.",
  steps=[('stmt',"const s = 'JavaScript'"),('expr',"s.slice(0, 4)",""),('expr',"s.substring(0, 4)","same here"),('expr',"s.slice(-6)","negative counts from the end"),('expr',"s.substring(-6)","negative becomes 0"),('expr',"s.substr(4, 3)","start + length (deprecated)")]),
 dict(title="What do match() and matchAll() do?", after="What is the difference between slice(), substring() and substr() for strings?",
  note="match with a normal regex returns the first match and its groups, and with the g flag it returns all matched strings. matchAll returns an iterator of every match with its groups, which I use when I need the captured parts of each match. Both return null or an empty result when nothing matches.",
  steps=[('stmt',"const s = 'a1 b22 c333'"),('expr',"s.match(/\\d+/g)","all numbers"),('expr',"s.match(/x/)","no match"),('expr',"[...s.matchAll(/(\\w)(\\d+)/g)].map((m) => m[1] + ':' + m[2])","groups of each match")]),
 dict(title="How do you compare strings with localeCompare()?", after="What do match() and matchAll() do?",
  note="localeCompare returns a negative number, 0 or a positive number, which is exactly what sort needs. It sorts letters correctly for a language, including accents, which the default sort gets wrong. I use arr.sort((a, b) => a.localeCompare(b)) for names.",
  steps=[('expr',"'a'.localeCompare('b')","a comes first"),('expr',"'b'.localeCompare('a')",""),('expr',"'a'.localeCompare('a')","equal"),('expr',"['zoo', 'Éclair', 'apple'].sort()","default: by character code"),('expr',"['zoo', 'Éclair', 'apple'].sort((a, b) => a.localeCompare(b, 'en'))","alphabetical")]),

 dict(title="What does Object.fromEntries() do?", after="What are Object.keys, values and entries?",
  note="Object.fromEntries turns a list of [key, value] pairs, or a Map, into an object. It's the opposite of Object.entries, so I use the two together to transform an object: entries, then map, then fromEntries.",
  steps=[('expr',"Object.fromEntries([['a', 1], ['b', 2]])",""),('stmt',"const prices = { apple: 50, mango: 80 }"),('expr',"Object.fromEntries(Object.entries(prices).map(([k, v]) => [k, v * 2]))","double every price")]),
 dict(title="What is the difference between Object.freeze() and Object.seal()?", after="What do Object.assign and Object.freeze do?",
  note="freeze makes an object fully read-only: no adding, removing or changing properties. seal blocks adding and removing properties, but existing ones can still be changed. Both are shallow, so nested objects stay editable; I check with Object.isFrozen and Object.isSealed.",
  steps=[('stmt',"const sealed = Object.seal({ x: 1 })"),('stmt',"const frozen = Object.freeze({ x: 1 })"),('expr',"Reflect.set(sealed, 'x', 2)","change: allowed"),('expr',"Reflect.set(sealed, 'y', 1)","add: blocked"),('expr',"Reflect.set(frozen, 'x', 2)","change: blocked"),('expr',"[Object.isSealed(sealed), Object.isFrozen(frozen)]","")]),
 dict(title="How do you check if an object has a property?", after="How do you add, update and delete properties in an object?",
  note="The in operator checks the object and its prototype chain, so it also finds inherited things like toString. Object.hasOwn(obj, key), the modern version of hasOwnProperty, checks only the object's own properties. I use Object.hasOwn in most code, and avoid obj.key !== undefined because a property can exist with the value undefined.",
  steps=[('stmt',"const user = { name: 'Anu', age: undefined }"),('expr',"'name' in user",""),('expr',"'toString' in user","inherited, still true"),('expr',"Object.hasOwn(user, 'toString')","own properties only"),('expr',"user.hasOwnProperty('name')","older way"),('expr',"Object.hasOwn(user, 'age')","exists even though it's undefined")]),
 dict(title="What do Object.create() and Object.getPrototypeOf() do?", after="What is the difference between Object.freeze() and Object.seal()?",
  note="Object.create(proto) makes a new empty object whose prototype is proto, so it inherits proto's methods without copying them. Object.getPrototypeOf returns an object's prototype. This is the prototype chain that classes use under the hood.",
  steps=[('stmt',"const animal = { speak() { return 'some sound' } }"),('stmt',"const dog = Object.create(animal)"),('expr',"dog.speak()","inherited"),('expr',"Object.hasOwn(dog, 'speak')","not its own property"),('expr',"Object.getPrototypeOf(dog) === animal","")]),
 dict(title="What is Object.is() and how is it different from ===?", after="What do Object.create() and Object.getPrototypeOf() do?",
  note="Object.is works like === except for two special cases: it treats NaN as equal to NaN, and it treats 0 and -0 as different. React uses Object.is to decide whether state changed.",
  steps=[('stmt',"const n = NaN"),('expr',"n === n","NaN is never === itself"),('expr',"Object.is(n, n)",""),('stmt',"const negZero = -0"),('expr',"negZero === 0","=== treats -0 and 0 as equal"),('expr',"Object.is(negZero, 0)",""),('expr',"Object.is('a', 'a')","")]),

 dict(title="What is the difference between parseInt(), parseFloat() and Number()?", after="How do you convert between strings, numbers and arrays?",
  note="parseInt and parseFloat read a number from the start of a string and stop at the first invalid character, so '42px' gives 42. Number() converts the whole value and returns NaN if any part isn't a number. I always pass a radix to parseInt, like parseInt(value, 10), and use Number() when the input must be a clean number.",
  steps=[('expr',"parseInt('42px', 10)","stops at 'p'"),('expr',"parseFloat('3.14abc')",""),('expr',"String(Number('42px'))","NaN: whole string must be a number"),('expr',"Number('')","empty string becomes 0"),('expr',"parseInt('101', 2)","binary to decimal")]),
 dict(title="What is the difference between toFixed() and toPrecision()?", after="What are the common number methods?",
  note="toFixed(n) rounds to n digits after the decimal point, and toPrecision(n) rounds to n significant digits in total. Both return a string, so I wrap them in Number() if I need to keep calculating. I use toFixed(2) for prices.",
  steps=[('expr',"(3.14159).toFixed(2)","2 decimals"),('expr',"(3.14159).toPrecision(3)","3 digits total"),('expr',"(0.1 + 0.2).toFixed(2)",""),('expr',"(1234.5).toPrecision(2)","switches to exponent form"),('expr',"typeof (5).toFixed(1)","always a string")]),
 dict(title="What do Number.isInteger(), Number.isFinite() and Number.isNaN() do?", after="What is the difference between toFixed() and toPrecision()?",
  note="Number.isInteger checks for whole numbers, Number.isFinite rejects Infinity and NaN, and Number.isNaN checks for the actual NaN value. Unlike the old global isNaN and isFinite, these don't convert strings first, so they don't give surprising results for input like '5'.",
  steps=[('expr',"Number.isInteger(5)",""),('expr',"Number.isInteger(5.5)",""),('expr',"Number.isFinite(1 / 0)","Infinity"),('expr',"[Number.isFinite('5'), isFinite('5')]","global one converts '5' first"),('expr',"[Number.isNaN('abc'), isNaN('abc')]","global one converts 'abc' first")]),
 dict(title="How does toString() convert numbers to other bases?", after="What is the difference between parseInt(), parseFloat() and Number()?",
  note="number.toString(radix) converts a number to text in another base, like 2 for binary or 16 for hex, and parseInt(text, radix) converts it back. Without a radix, toString gives the normal decimal text, and arrays join their items with commas.",
  steps=[('expr',"(255).toString(16)","hex"),('expr',"(5).toString(2)","binary"),('expr',"parseInt('ff', 16)","hex back to number"),('expr',"(123).toString()",""),('expr',"[1, 2, 3].toString()","")]),
 dict(title="What is the difference between Math.round(), Math.floor(), Math.ceil() and Math.trunc()?", after="What are the common Math methods?",
  note="round goes to the nearest whole number, floor always goes down, ceil always goes up, and trunc just removes the decimals. The difference shows with negative numbers: floor(-4.7) is -5 but trunc(-4.7) is -4. I use floor for things like page numbers and ceil for the total number of pages.",
  steps=[('expr',"[Math.round(4.7), Math.floor(4.7), Math.ceil(4.7), Math.trunc(4.7)]",""),('expr',"[Math.round(-4.7), Math.floor(-4.7), Math.ceil(-4.7), Math.trunc(-4.7)]","negatives differ"),('expr',"Math.ceil(23 / 10)","pages needed for 23 items")]),
 dict(title="How do you get a random number in a range?", after="What is the difference between Math.round(), Math.floor(), Math.ceil() and Math.trunc()?",
  note="Math.random() returns a decimal from 0 up to, but not including, 1. To get a whole number between min and max, I multiply by the size of the range, floor it and add min. For anything security-related, like tokens, I use crypto.getRandomValues instead.",
  steps=[('stmt',"const randomInt = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min"),('stmt',"const dice = randomInt(1, 6)"),('expr',"dice >= 1 && dice <= 6","always in range")]),
 dict(title="What do Math.pow(), Math.sqrt(), Math.abs() and Math.sign() do?", after="How do you get a random number in a range?",
  note="Math.pow(a, b) raises a to a power, which I usually write as a ** b. Math.sqrt gives the square root, Math.abs removes the sign, and Math.sign returns -1, 0 or 1. Math.max and Math.min take separate numbers, so I spread an array into them.",
  steps=[('expr',"[Math.pow(2, 3), 2 ** 3]",""),('expr',"Math.sqrt(16)",""),('expr',"Math.abs(-7)",""),('expr',"[Math.sign(-3), Math.sign(0), Math.sign(5)]",""),('expr',"Math.max(...[1, 5, 3])","")]),
]
